import { computed, defineComponent, h, ref, type PropType } from 'vue';
import { getNativeSelectState, nativeSelectStyleKeys } from '../lib/core';
import type { NativeSelectSize } from '../lib/core';
import styles from './native-select.module.scss';

export const NativeSelect = defineComponent({
	name: 'NativeSelect',
	props: {
		modelValue: { type: String, default: undefined },
		defaultValue: { type: String, default: '' },
		size: {
			type: String as PropType<NativeSelectSize>,
			default: 'default',
		},
		disabled: { type: Boolean, default: false },
	},
	emits: ['update:modelValue', 'change'],
	setup(props, { emit, attrs, slots }) {
		const internalValue = ref(props.defaultValue);
		const currentValue = computed(() => (props.modelValue !== undefined ? props.modelValue : internalValue.value));
		const state = computed(() => getNativeSelectState(currentValue.value));

		function handleChange(event: Event) {
			const next = (event.target as HTMLSelectElement).value;
			if (props.modelValue === undefined) {
				internalValue.value = next;
			}
			emit('update:modelValue', next);
			emit('change', next);
		}

		return () =>
			h('div', { class: styles[nativeSelectStyleKeys.wrapper] }, [
				h(
					'select',
					{
						...attrs,
						'data-slot': 'native-select',
						'data-size': props.size,
						'data-state': state.value,
						value: currentValue.value,
						disabled: props.disabled,
						class: [styles[nativeSelectStyleKeys.select], attrs.class],
						onChange: handleChange,
					},
					slots.default?.(),
				),
				h(
					'svg',
					{
						class: styles[nativeSelectStyleKeys.icon],
						xmlns: 'http://www.w3.org/2000/svg',
						viewBox: '0 0 24 24',
						fill: 'none',
						stroke: 'currentColor',
						'stroke-width': '2',
						'stroke-linecap': 'round',
						'stroke-linejoin': 'round',
						'aria-hidden': 'true',
						'data-slot': 'native-select-icon',
					},
					[h('path', { d: 'm6 9 6 6 6-6' })],
				),
			]);
	},
});

export const NativeSelectOption = defineComponent({
	name: 'NativeSelectOption',
	props: {
		value: { type: String, default: undefined },
		label: String,
		disabled: { type: Boolean, default: false },
	},
	setup(props, { attrs, slots }) {
		return () =>
			h(
				'option',
				{
					...attrs,
					'data-slot': 'native-select-option',
					value: props.value,
					label: props.label,
					disabled: props.disabled,
					class: [styles[nativeSelectStyleKeys.option], attrs.class],
				},
				slots.default?.(),
			);
	},
});

export const NativeSelectOptGroup = defineComponent({
	name: 'NativeSelectOptGroup',
	props: {
		label: String,
		disabled: { type: Boolean, default: false },
	},
	setup(props, { attrs, slots }) {
		return () =>
			h(
				'optgroup',
				{
					...attrs,
					'data-slot': 'native-select-optgroup',
					label: props.label,
					disabled: props.disabled,
					class: [styles[nativeSelectStyleKeys.optGroup], attrs.class],
				},
				slots.default?.(),
			);
	},
});

export default NativeSelect;

@use '../../../styles/variables/colors' as *;

.wrapper {
	position: relative;
	width: fit-content;
	color: $foreground;

	&:has(select:disabled) {
		opacity: 0.5;
	}
}

.select {
	appearance: none;
	width: 100%;
	min-width: 0;
	height: var(--tile-native-select-height, 2.25rem);
	border-radius: var(--tile-native-select-radius, #{$radius});
	border: var(--tile-native-select-border-width, 1px) solid var(--tile-native-select-border, #{$input});
	background-color: var(--tile-native-select-background, #{$background});
	padding: var(--tile-native-select-padding, #{$spacing-2} 2.25rem #{$spacing-2} #{$spacing-3});
	font-size: var(--tile-native-select-font-size, #{$text-sm});
	line-height: var(--tile-native-select-line-height, inherit);
	color: $foreground;
	box-shadow: var(--tile-native-select-shadow, #{$shadow-sm});
	transition:
		border-color $transition-fast,
		box-shadow $transition-fast;
	outline: none;
	cursor: pointer;

	&::placeholder {
		color: $muted-foreground;
	}

	&:hover:not(:disabled) {
		background-color: var(--tile-native-select-hover-background, #{$field-hover});
	}

	&:focus-visible {
		border-color: var(--tile-native-select-focus-border, #{$ring});
		box-shadow: var(--tile-native-select-focus-shadow, 0 0 0 3px color-mix(in srgb, #{$ring} 50%, transparent));
	}

	&:disabled {
		pointer-events: none;
		cursor: not-allowed;
	}

	&[data-size='sm'] {
		height: var(--tile-native-select-sm-height, 2rem);
		font-size: var(--tile-native-select-sm-font-size, #{$text-sm});
		border-radius: var(--tile-native-select-sm-radius, #{$radius});
		padding-top: $spacing-1;
		padding-bottom: $spacing-1;
	}

	&[data-state='empty'] {
		color: $muted-foreground;
	}

	&[aria-invalid='true'] {
		border-color: $destructive;
		box-shadow: var(--tile-native-select-error-shadow, #{$shadow-sm});

		&:focus-visible {
			box-shadow: var(--tile-native-select-error-focus-shadow, 0 0 0 3px color-mix(in srgb, #{$destructive} 20%, transparent));
		}
	}
}

.icon {
	pointer-events: none;
	position: absolute;
	top: 50%;
	right: 0.875rem;
	transform: translateY(-50%);
	width: 1rem;
	height: 1rem;
	color: $muted-foreground;
	opacity: 0.5;
	user-select: none;
}

.option {
	background-color: Canvas;
	color: CanvasText;
}

.optGroup {
	background-color: Canvas;
	color: CanvasText;
}
